            if delta.Magnitude > 4 then floatMoved = true end
            floating.Position = UDim2.new(floatPosition.X.Scale, floatPosition.X.Offset + delta.X,
                floatPosition.Y.Scale, floatPosition.Y.Offset + delta.Y)
